import { CLAUDE_OFFICIAL_MARKETPLACE, HOST_FACTS, type ManagedSettingsHost } from './hosts.js';
import type { ManagedSettingsFile, ManagedSettingsPlan } from './index.js';

type Base = Omit<ManagedSettingsPlan, 'files'>;

const GENERATED_NOTE =
  'Generated by `bluetemberg managed-settings`. Regenerate it instead of editing it; sync never touches these files.';

/** How this README starts; `writeManagedSettings` only overwrites a README that starts this way. */
export const README_MARKER = `# Managed settings\n\n${GENERATED_NOTE}`;

function pluginLine(base: Base): string {
  const name = base.marketplace.name;
  const list = (plugins: string[] | undefined): string =>
    (plugins ?? []).map((p) => `\`${p}@${name}\``).join(', ');
  if (base.hosts.length === 1) return list(base.pluginsByHost[base.hosts[0]]);
  return base.hosts.map((h) => `${HOST_FACTS[h].label}: ${list(base.pluginsByHost[h])}`).join('; ');
}

function summary(base: Base): string[] {
  const { name, repo, ref, autoUpdate } = base.marketplace;
  const pin = ref
    ? `pinned to \`${ref}\``
    : 'not pinned: hosts read the repository default branch (pass `--ref <tag>` to pin)';
  return [
    `- **Marketplace:** \`${name}\` from GitHub \`${repo}\`, ${pin}.`,
    `- **Auto-update:** ${autoUpdate ? 'on (`autoUpdate: true`)' : 'left to each client (no `autoUpdate` key)'}.`,
    `- **Plugins force-enabled:** ${pluginLine(base)}.`,
    `- **Marketplace allowlist (\`strictKnownMarketplaces\`):** ${base.strict ? 'on' : 'off'}.`,
    `- **MCP allowlist (\`allowedMcpServers\`):** ${base.mcpServers.length > 0 ? base.mcpServers.map((s) => `\`${s}\``).join(', ') : 'off'}.`,
    `- **Telemetry export:** ${base.telemetry ? `on, to \`${base.telemetry.endpoint}\` (see "What is sent, and where")` : 'off (pass `--telemetry-endpoint` to turn it on)'}.`,
  ];
}

function driftNote(base: Base): string {
  return base.driftChecked
    ? '`bluetemberg managed-settings` checked the Agent Plugins bundle locks against `packages-lock.json`, but it cannot see the remote repo'
    : 'these bundles were NOT checked against `packages-lock.json`, because only Agent Plugins bundles carry a lock; run `bluetemberg sync --check` before publishing';
}

function packsSection(base: Base): string[] {
  const rows = Object.entries(base.packs).map(([n, p]) => `| \`${n}\` | ${p.version} | \`${p.integrity}\` |`);
  if (rows.length === 0) return ['No packs are recorded in `packages-lock.json`.'];
  return [
    'Neither host pins a plugin version: `enabledPlugins` only names `plugin@marketplace`. What users get is',
    'whatever the marketplace repo holds at the pinned ref, so make sure that ref holds bundles built from',
    `these packs (${driftNote(base)}):`,
    '',
    '| Pack | Version | Integrity |',
    '| - | - | - |',
    ...rows,
  ];
}

function pathsTable(host: ManagedSettingsHost): string[] {
  const rows = HOST_FACTS[host].filePaths.map(({ os, path }) => `| ${os} | \`${path}\` |`);
  return ['| OS | Path |', '| - | - |', ...rows];
}

function claudeSection(file: string): string[] {
  return [
    '## Claude Code',
    '',
    `File: \`${file}\`. Copy it to the system path for each OS:`,
    '',
    ...pathsTable('claude'),
    '',
    'If the machine already has a `managed-settings.json`, deploy this file as a drop-in instead, for',
    'example `managed-settings.d/50-bluetemberg.json` in the same directory. Claude Code merges drop-ins',
    'after the main file in name order: lists combine, and a same-named `extraKnownMarketplaces` entry',
    'is replaced whole. Claude Code does not read the legacy `C:\\ProgramData\\ClaudeCode` path.',
    '',
    'Other delivery: a macOS configuration profile in the `com.anthropic.claudecode` domain (same',
    'top-level keys), the JSON as a `REG_SZ` value named `Settings` under',
    '`HKLM\\SOFTWARE\\Policies\\ClaudeCode` on Windows, or the claude.ai admin console (server-managed',
    'settings, the only source that reaches cloud sessions).',
    '',
    'Check one machine with `/status`: the `Setting sources` line shows the managed source.',
    '',
  ];
}

function copilotMdmRows(content: string): string[] {
  const parsed = JSON.parse(content) as Record<string, unknown>;
  return Object.entries(parsed).map(([key, value]) => `| \`${key}\` | \`${JSON.stringify(value)}\` |`);
}

function copilotSection(file: ManagedSettingsFile): string[] {
  return [
    '## GitHub Copilot',
    '',
    `File: \`${file.path}\`. Pick one delivery method:`,
    '',
    '- **Server-managed:** commit it as `copilot/managed-settings.json` in the enterprise `.github-private`',
    '  repository (default branch). Clients pick it up within about an hour.',
    '- **File-based:** copy it to the system path below. On macOS and Linux the Copilot CLI only reads a',
    '  regular file owned by `root` that is not group- or world-writable, and rejects a symbolic link.',
    '  Users restart their clients to load it.',
    '',
    ...pathsTable('copilot'),
    '',
    '- **MDM (macOS and Windows):** no file. Set each top-level key as a string value in the',
    '  `com.github.copilot` managed preferences domain, or as a `REG_SZ` value under',
    '  `HKEY_LOCAL_MACHINE\\SOFTWARE\\Policies\\GitHubCopilot`. Objects and arrays are stored as JSON text:',
    '',
    '| Key | String value |',
    '| - | - |',
    ...copilotMdmRows(file.content),
    '',
    'Copilot has no drop-in directory: if you already deploy a `managed-settings.json`, merge these keys',
    'into it. MDM settings win over server-managed ones, which win over the file.',
    '',
  ];
}

function strictSection(base: Base): string[] {
  if (!base.strict) return [];
  return [
    '## Before you deploy the marketplace allowlist',
    '',
    '`strictKnownMarketplaces` blocks every marketplace it does not list, for adding, installing and',
    'updating alike, including marketplaces users added themselves before the policy:',
    '',
    `- **Claude Code** also blocks its official marketplace (\`${CLAUDE_OFFICIAL_MARKETPLACE}\`) unless you`,
    '  list it with `--allow-marketplace`. The file includes `{ "source": "skills-dir" }` so',
    '  skills-directory plugins keep loading.',
    '- **GitHub Copilot** turns off its built-in marketplaces.',
    '- Matching is exact, `ref` included: an entry pinned to a ref does not match the same repository added',
    '  without one. Users who added this marketplace before it was pinned may need to remove it',
    '  (`claude plugin marketplace remove <name>`) so the managed entry registers.',
    '',
  ];
}

function mcpSection(base: Base, source: string): string[] {
  const allow =
    base.mcpServers.length > 0
      ? [
          `\`allowedMcpServers\` lists the servers in \`${source}/mcp.json\` and the root \`.mcp.json\` by exact command or URL. Every other MCP`,
          'server users add is blocked. Claude Code merges allowlists from every settings file; Copilot',
          'intersects them, so a narrower list elsewhere still wins there. A command is matched exactly,',
          'arguments included: a server started another way (for example `cmd /c npx …` on Windows) needs its',
          'own entry.',
        ]
      : ["No MCP allowlist was written (pass `--mcp-allowlist` to list this project's servers)."];
  return [
    '## MCP servers',
    '',
    ...allow,
    '',
    'No `deniedMcpServers` list is written: bluetemberg has nothing it could truthfully deny. If you add',
    'one, a deny entry beats every allow entry in both hosts, so check it against the servers this',
    'project uses.',
    '',
  ];
}

function telemetryHostRows(base: Base): string[] {
  const rows: string[] = [];
  if (base.hosts.includes('claude')) {
    rows.push(
      '- **Claude Code** (`env`): metrics (sessions, tokens, cost, lines changed, commits, pull requests,',
      '  active time, edit accept/reject) and events (prompt *length*, tool name/success/duration, API',
      '  request model/tokens/cost/errors). Traces are off (`OTEL_TRACES_EXPORTER=none`). Prompts,',
      '  responses, tool input and output, Bash commands and custom skill/plugin/MCP names stay redacted:',
      '  `OTEL_LOG_USER_PROMPTS`, `OTEL_LOG_ASSISTANT_RESPONSES`, `OTEL_LOG_TOOL_DETAILS` and',
      '  `OTEL_LOG_TOOL_CONTENT` are set to `0` in policy, which no user or project setting overrides.',
      '  **Identity:** Claude Code always attaches `user.email`, `user.account_uuid` and `organization.id`',
      '  when the user is signed in; no setting removes them. Drop them in your collector if you must',
      '  (an `attributes` processor with `action: delete`).',
    );
  }
  if (base.hosts.includes('copilot')) {
    rows.push(
      '- **GitHub Copilot** (`telemetry`): traces, metrics and events about sessions, model calls and tool',
      '  use. Every `capture` class is `false` (identity, prompts, responses, tool arguments, tool output,',
      '  policy detail) and `lockCaptureContent` stops local settings from turning content on. Copilot',
      '  applies managed `telemetry` in the CLI, VS Code, the Copilot app and JetBrains IDEs, not in',
      '  cloud sessions.',
    );
  }
  return rows;
}

function telemetrySection(base: Base): string[] {
  const t = base.telemetry;
  if (!t) return [];
  const attrs = Object.entries(t.attributes).map(([k, v]) => `| \`${k}\` | \`${v}\` |`);
  return [
    '## What is sent, and where',
    '',
    `Each host's own exporter sends OTLP (\`${t.protocol}\`) to **\`${t.endpoint}\`**, your collector, and`,
    'nowhere else. bluetemberg sends nothing, runs nothing and stores nothing; these keys only configure',
    'the hosts.',
    '',
    ...telemetryHostRows(base),
    '',
    'Every metric and event carries these resource attributes:',
    '',
    '| Attribute | Value |',
    '| - | - |',
    ...attrs,
    '',
    ...(t.packsDigest
      ? [
          `\`bluetemberg.packs.digest\` identifies the pack set in "Pack versions" above. It changes exactly when a`,
          'pack version changes, so a dashboard can split cost, tool errors or edit rejections by rule version.',
          '',
        ]
      : []),
    '### Before you deploy telemetry',
    '',
    '- **No credentials are written.** Authenticate with a header helper the host runs: Claude Code',
    '  `otelHeadersHelper` (a command that prints a JSON object of headers) and Copilot',
    '  `telemetry.headersProvider`. Static headers in a policy file are readable by every user.',
    '- **One attribute list per host.** Claude Code merges managed `env` per variable, so another source',
    '  that sets `OTEL_RESOURCE_ATTRIBUTES` replaces this one, or this one replaces it. Copilot takes the',
    '  whole `telemetry` object from the highest-precedence managed source. Carry your own keys here with',
    '  `--telemetry-attribute key=value` instead of setting them elsewhere.',
    '- **Endpoint lock.** In Claude Code a managed `OTEL_EXPORTER_OTLP_ENDPOINT` removes endpoints users',
    '  set per signal, so all metrics and events go to the endpoint above.',
    '',
  ];
}

function docsSection(base: Base): string[] {
  return [
    '## Host documentation',
    '',
    ...base.hosts.flatMap((h) =>
      HOST_FACTS[h].docs.map((d) => `- ${HOST_FACTS[h].label}: [${d.label}](${d.url})`),
    ),
    '',
  ];
}

export function renderReadme(base: Base, files: ManagedSettingsFile[], source: string): string {
  const hostSections = files.flatMap((f) => {
    if (f.host === 'claude') return claudeSection(f.path);
    if (f.host === 'copilot') return copilotSection(f);
    return [];
  });
  const warnings =
    base.warnings.length > 0 ? ['## Warnings', '', ...base.warnings.map((w) => `- ${w}`), ''] : [];
  return [
    '# Managed settings',
    '',
    GENERATED_NOTE,
    '',
    ...summary(base),
    '',
    '## Pack versions',
    '',
    ...packsSection(base),
    '',
    ...hostSections,
    ...strictSection(base),
    ...mcpSection(base, source),
    ...telemetrySection(base),
    ...warnings,
    ...docsSection(base),
  ].join('\n');
}
